// A IdentityManager manages the issuance of JWT identity tokens.
type IdentityManager interface {
	// IssueIdentityToken issues a new identity token.
	IssueIdentityToken(context.Context, *IssueIdentityTokenRequest) (*IssueIdentityTokenResponse, error)

	// DiscoveryDocument returns the data relevant to the creation of an OpenID Connect Discovery Document.
	DiscoveryDocument(context.Context, *DiscoveryDocumentRequest) (*DiscoveryDocumentResponse, error)

	// JWKS returns the JSON Web Key Set. This data is formated specifically for a JWKS endpoint.  If other clients within GitHub want to retrieve the public keys, it's probably best to create a new endpoint with a more structured data set.
	Jwks(context.Context, *JwksRequest) (*JwksResponse, error)
}

