// =============================
// MobileDeviceManager Interface
// =============================

// A MobileDeviceManager manages the registration and authentication methods for mobile devices
type MobileDeviceManager interface {
	// RegisterDeviceKey registers a public key for a mobile device that can be used for authentication or recovery requests.
	RegisterDeviceKey(context.Context, *RegisterDeviceKeyRequest) (*RegisterDeviceKeyResponse, error)

	// RevokeDeviceKey revokes a public key for a mobile device so that it can no longer be used.
	RevokeDeviceKey(context.Context, *RevokeDeviceKeyRequest) (*RevokeDeviceKeyResponse, error)

	// RevokeDeviceKeys revokes all mobile device keys for a given user so they can no longer be used.
	RevokeDeviceKeys(context.Context, *RevokeDeviceKeysRequest) (*RevokeDeviceKeysResponse, error)

	// FindDeviceKeyRegistrations gets all registered mobile device registrations for a user.
	FindDeviceKeyRegistrations(context.Context, *FindDeviceKeyRegistrationsRequest) (*FindDeviceKeyRegistrationsResponse, error)

	// FindDeviceKeyRegistration retrieves a device key registration associated with a user device.
	FindDeviceKeyRegistration(context.Context, *FindDeviceKeyRegistrationRequest) (*FindDeviceKeyRegistrationResponse, error)

	// RequestDeviceAuth begins the process of authenticating using a user device.
	RequestDeviceAuth(context.Context, *RequestDeviceAuthRequest) (*RequestDeviceAuthResponse, error)

	// GetDeviceAuthStatus retrieves the status (active, approved, rejected, expired) of a device auth request.
	GetDeviceAuthStatus(context.Context, *GetDeviceAuthStatusRequest) (*GetDeviceAuthStatusResponse, error)

	// FindActiveDeviceAuth finds an active device auth request.
	FindActiveDeviceAuth(context.Context, *FindActiveDeviceAuthRequest) (*FindActiveDeviceAuthResponse, error)

	// CompleteDeviceAuth approves or rejects an active device auth request.
	CompleteDeviceAuth(context.Context, *CompleteDeviceAuthRequest) (*CompleteDeviceAuthResponse, error)
}

